413	    /** The settings view of a sheet as it stood at the end of a day. */
414	    private SettingsView view(String id, History.SheetAsOf then) {
415	        LocalDate day = then.day();
416	        Function<String, BigDecimal> value = key -> then.setting(key, day).map(SettingValue::getValue).orElse(null);
417	        Map<String, Integer> gradeTerms = new TreeMap<>();
418	        for (String grade : service.grades(id)) {
419	            then.setting("terms-" + grade, day).ifPresent(v -> gradeTerms.put(grade, v.getValue().intValue()));
420	        }
421	        int terms = then.setting("terms", day).map(v -> v.getValue().intValue()).orElse(SheetService.STARTING_TERMS);
422	        Map<String, Integer> gradeGraces = new TreeMap<>();
423	        Map<String, List<SettingValue>> graces = new TreeMap<>();
424	        for (String grade : service.grades(id)) {
425	            then.setting("grace-" + grade, day).map(SettingValue::getValue)
426	                    .ifPresent(v -> gradeGraces.put(grade, v.intValue()));
427	            graces.put(grade, then.recorded("grace-" + grade));
428	        }
429	        Map<String, BigDecimal> gradeProofThresholds = new TreeMap<>();
430	        for (String grade : service.grades(id)) {
431	            then.setting("proof-threshold-" + grade, day).map(SettingValue::getValue)
432	                    .ifPresent(v -> gradeProofThresholds.put(grade, v));
433	        }
434	        Map<String, BigDecimal> gradeClerkLimits = new TreeMap<>();
435	        for (String grade : service.grades(id)) {
436	            then.setting("clerk-limit-" + grade, day).map(SettingValue::getValue)
437	                    .ifPresent(v -> gradeClerkLimits.put(grade, v));
438	        }
439	        return SettingsView.of(value.apply("clerk-limit"), then.basis().floor(day), terms, then.basis().latePct(day),
440	                then.policyDate(), service.periodNumberingFrom(id), gradeTerms, then.basis().cap(),
441	                then.recorded("floor"), then.recorded("late-pct"), then.recorded("cap"),
442	                value.apply("proof-threshold"), service.permissions(id), service.graceDays(id),
443	                value.apply("note-threshold"), service.entryDate(id), gradeGraces, graces,
444	                gradeProofThresholds, service.pot(id), service.parent(id), service.fiscalStartMonth(id),
445	                service.alertThreshold(id),
446	                then.setting(Rounding.KEY, day).map(SettingValue::getValue).flatMap(Rounding::ofCode),
447	                then.recorded(Rounding.KEY), value.apply("review-threshold"), service.escalateAfter(id),
448	                service.reviewSla(id), service.proofKinds(id), service.defaultGradeSet(id), gradeClerkLimits,
449	                service.scoreMid(id), service.scoreHigh(id), service.scoreLog(id), service.maxOpen(id), service.pendingSla(id));
450	    }
